      var list = listOf(0)
      list += 42 // A new list is allocated here, equivalent to list = list + 42
  }' After the quick-fix is applied: 'fun test() {
      val list = mutableListOf(0)
      list += 42
  }' Inspection ID: SuspiciousCollectionReassignment

